input.command:
cd "C:/visual projects/alpha" && ssh calc 'cd /data/tk0393/tk410; head -2 cover.csv; ls mid-all | grep -v csv | head; python3 - <<EOF
import csv,os,glob,collections
S="/data/tk0393"
have={}
for f in glob.glob(S+"/sqd*/*/summary.csv"):
    for l in open(f).read().splitlines()[1:]: have.setdefault(l.split(",")[0].lower(),set()).add("sqd")
for d in ("mid-all","mid-eth"):
    for f in os.listdir(d):
        if "__" in f and f.endswith(".csv"):
            p=f.split("__")[1][:-4]
            if os.path.getsize(d+"/"+f)>60: have.setdefault(p,set()).add(d)
c=collections.Counter(); miss=[]
for r in csv.DictReader(open("cover.csv")):
    cl=r["class"]; ch=r["chain"]
    if ch in("solana","sui","tron"): k="non-evm:"+ch
    elif r["pool"].lower() in have: k="mid"
    else: k="none"; miss.append((r["coin"],ch,r["dex"]))
    c[(cl,k)]+=1
for k,v in sorted(c.items()): print(k,v)
print(miss[:40])
EOF' 2>&1

